}

import { KiroPlugin } from "./plugin.js";
export { AcpJsonRpcClient, createAcpStdioClient, decodeJsonRpc, encodeJsonRpc } from "./acp-client.js";
export { acpPermissionResponse, KiroAcpTransport } from "./acp-transport.js";
export { createKiroPlugin, effectiveBackend, KiroPlugin } from "./plugin.js";
export { authorizeKiroDevice, credentialFromKiroDeviceAuthKey, decodeKiroDeviceAuthKey, detectAuth, encodeKiroDeviceAuthKey, extractKiroLoginUrl, isKiroDeviceAuthKey, kiroDeviceVerificationUrl, pollKiroDeviceToken, KIRO_LOGIN_URL, readKiroCliSessionCredential, redacted, regionFromProfileArn, refreshKiroDeviceAuthCredential, resolveApiKey, runKiroLoginFlowOnce, startKiroCliLogin, startKiroCliLoginOnce, } from "./auth.js";
export { cliChatArgs, KiroCliChatTransport, promptForCli } from "./cli-transport.js";
export { createKiroFetch } from "./fetch-adapter.js";
export { loadOptions } from "./config.js";
export { getKiroCliStatus, getKiroCliVersion } from "./kiro-cli.js";
export { additionalModelRequestFields, CodeWhispererKiroTransport, collectAssistantText, createCodeWhispererClient, streamAssistantText, toGenerateAssistantResponseInput, usageFromMetadataEvent, } from "./kiro-transport.js";
export { KiroRestTransport, toKiroRestPayload } from "./kiro-rest-transport.js";
export { ModelCache } from "./model-cache.js";
export { discoverModelsFromCommand, isModelDiscoveryAuthFailure, parseDiscoveredModels, refreshModelCacheFromCommand } from "./model-discovery.js";
export { ModelResolutionError, ModelResolver, normalizeModelName } from "./model-resolver.js";
export { FALLBACK_MODELS } from "./models.js";
export { toKiroGenerateRequest } from "./request-adapter.js";
export { toOpenAIChatResponse, toOpenAIChatStreamResponse } from "./response-adapter.js";
export default {
    id: "kiro",
    server: KiroPlugin,
};

import { tool } from "@opencode-ai/plugin";
import { spawn } from "node:child_process";
import { KiroAcpTransport } from "./acp-transport.js";
import { authorizeKiroDevice, credentialFromKiroDeviceAuthKey, detectAuth, encodeKiroDeviceAuthKey, isKiroDeviceAuthKey, kiroDeviceVerificationUrl, KIRO_LOCAL_TRANSPORT_KEY, pollKiroDeviceToken, readKiroCliSessionCredential, resolveApiKey, startKiroCliLoginOnce, runKiroLoginFlowOnce, } from "./auth.js";
import { KiroCliChatTransport } from "./cli-transport.js";
import { loadOptions } from "./config.js";
import { createKiroFetch } from "./fetch-adapter.js";
import { startLocalKiroServer } from "./local-server.js";
import { ModelCache } from "./model-cache.js";
import { discoverModelsFromCommand } from "./model-discovery.js";
import { loadStoredModelCache, saveStoredModelCache } from "./model-cache-store.js";
import { ModelResolver, normalizeModelName } from "./model-resolver.js";
import { KiroRestTransport } from "./kiro-rest-transport.js";
const PLACEHOLDER_MODEL_ID = "auto";
const PLACEHOLDER_MODEL = { name: "Auto" };
const OPENCODE_AGENT_HEADER = "x-opencode-kiro-agent";
const LOGIN_SUPPRESSED_AGENTS = new Set(["title"]);
const LOGIN_METHODS = new Set(["builder-id", "google", "github", "organization"]);
let sharedDeviceAuthKey;
function discoveredProviderModels(cache) {
    return Object.fromEntries(cache.all().map((model) => [
        model.id,
        {
            name: model.name ?? model.id,
            ...(model.contextLimit || model.outputLimit
                ? {
                    limit: {
                        context: model.contextLimit ?? 200_000,
                        output: model.outputLimit ?? 64_000,
                    },
                }
                : {}),
        },
    ]));
}
function modelRecord(value) {
    if (!value || typeof value !== "object" || Array.isArray(value))
        return {};
    return Object.fromEntries(Object.entries(value).filter((entry) => Boolean(entry[0]) && Boolean(entry[1]) && typeof entry[1] === "object" && !Array.isArray(entry[1])));
}
function visibleProviderModels(cache, configuredModels, hiddenModels, disabledModels) {
    const discovered = discoveredProviderModels(cache);
    const modelIDs = new Set([...Object.keys(discovered), ...Object.keys(configuredModels), ...Object.keys(hiddenModels)]);
    const models = Object.fromEntries([...modelIDs]
        .filter((id) => !disabledModels.has(normalizeModelName(id)))
        .map((id) => [
        id,
        {
            ...(discovered[id] ?? {}),
            ...(configuredModels[id] ?? {}),
        },
    ]));
    if (Object.keys(models).length > 0 || disabledModels.has(PLACEHOLDER_MODEL_ID))
        return models;
    return { [PLACEHOLDER_MODEL_ID]: PLACEHOLDER_MODEL };
}
function extraModelInfos(models) {
    return Object.keys(models).map((id) => ({ id: normalizeModelName(id) }));
}
function mergeModelInfos(discovered, extraModels) {
    return [...new Map([...discovered, ...extraModelInfos(extraModels)].map((model) => [model.id, model])).values()];
}
function bearerToken(init) {
    const header = new Headers(init?.headers).get("authorization");
    const match = header?.match(/^Bearer\s+(.+)$/i);
    return match?.[1] || undefined;
}
function isLikelyKiroApiKey(value) {
    return Boolean(value?.startsWith("ksk_"));
}
function localAccessToken(incoming, fallback) {
    if (!incoming || incoming === KIRO_LOCAL_TRANSPORT_KEY)
        return fallback ?? incoming;
    if (isKiroDeviceAuthKey(incoming))
        return incoming;
    if (process.env.KIRO_API_KEY && incoming === process.env.KIRO_API_KEY)
        return incoming;
    if (isLikelyKiroApiKey(incoming))
        return incoming;
    return fallback;
}
export function effectiveBackend(options, accessToken) {
    const apiKey = accessToken || process.env.KIRO_API_KEY;
    if (options.backend === "acp")
        return "acp";
    if (options.backend === "cli-chat")
        return "cli-chat";
    if (options.backend === "fetch")
        return "fetch";
    if (apiKey && apiKey !== KIRO_LOCAL_TRANSPORT_KEY)
        return "fetch";
    return "fetch";
}
function shouldLoginOnAuthFailure(init) {
    const agent = new Headers(init?.headers).get(OPENCODE_AGENT_HEADER);
    return !agent || !LOGIN_SUPPRESSED_AGENTS.has(agent);
}
function inputString(inputs, key) {
    const value = inputs?.[key]?.trim();
    return value || undefined;
}
function loginOptions(base, inputs) {
    const inputMethod = inputString(inputs, "method");
    const method = inputMethod && LOGIN_METHODS.has(inputMethod) ? inputMethod : undefined;
    const identityProvider = inputString(inputs, "identityProvider");
    const region = inputString(inputs, "region");
    return {
        ...base,
        ...(method ? { method } : {}),
        ...(identityProvider ? { identityProvider } : {}),
        ...(region ? { region } : {}),
        useDeviceFlow: true,
    };
}
function isOrganizationLogin(login) {
    return login.method === "organization" || login.license === "pro" || Boolean(login.identityProvider || login.region);
}
function isKiroCliModelDiscoveryCommand(command) {
    const executable = command[0]?.split(/[\\/]/).pop();
    return executable === "kiro-cli" && command.includes("chat") && command.includes("--list-models");
}
function openExternalUrl(url) {
    if (process.env.OPENCODE_KIRO_BROWSER_OPEN === "0")
        return;
    const command = process.platform === "darwin" ? "open" : process.platform === "win32" ? "cmd" : "xdg-open";
    const args = process.platform === "win32" ? ["/c", "start", "", url] : [url];
    const child = spawn(command, args, { detached: true, stdio: "ignore" });
    child.on("error", () => undefined);
    child.unref();
}
function rememberDeviceAuthKey(key) {
    sharedDeviceAuthKey = key;
    return key;
}
export function __resetKiroPluginSharedStateForTest() {
    sharedDeviceAuthKey = undefined;
}
function loginPrompts(options) {
    const prompts = [];
    const login = options.login;
    const hasLoginRoute = Boolean(login.method || login.license || login.identityProvider || login.region);
    if (!hasLoginRoute) {
        prompts.push({
            type: "select",
            key: "method",
            message: "Select Kiro login method",
            options: [
                { label: "Use with Builder ID", value: "builder-id" },
                { label: "Use with Google", value: "google" },
                { label: "Use with GitHub", value: "github" },
                { label: "Use with Your Organization", value: "organization" },
            ],
        });
    }
    const organizationIsConfigured = login.method === "organization" || login.license === "pro" || Boolean(login.identityProvider || login.region);
    const organizationWhen = hasLoginRoute ? undefined : { key: "method", op: "eq", value: "organization" };
    if (organizationIsConfigured || !hasLoginRoute) {
        if (!login.identityProvider) {
            prompts.push({
                type: "text",
                key: "identityProvider",
                message: "IAM Identity Center Start URL",
                placeholder: "https://example.awsapps.com/start",
                ...(organizationWhen ? { when: organizationWhen } : {}),
            });
        }
        if (!login.region) {
            prompts.push({
                type: "text",
                key: "region",
                message: "IAM Identity Center region",
                placeholder: "ap-northeast-2",
                ...(organizationWhen ? { when: organizationWhen } : {}),
            });
        }
    }
    return prompts.length > 0 ? prompts : undefined;
}
function localTransport(options, accessToken, behavior = {}) {
    const backend = effectiveBackend(options, accessToken);
    const login = () => {
        if (behavior.loginOnAuthFailure === false)
            return Promise.resolve(false);
        if (isKiroDeviceAuthKey(accessToken))
            return Promise.resolve(false);
        return runKiroLoginFlowOnce({
            login: loginOptions(options.login),
        });
    };
    if (backend === "acp")
        return new KiroAcpTransport(acpTransportOptions(options));
    if (backend === "cli-chat") {
        return new KiroCliChatTransport({
            trustAllTools: options.trustAllTools,
            ...(options.requestTimeoutMs ? { requestTimeoutMs: options.requestTimeoutMs } : {}),
            login,
        });
    }
    if (backend === "fetch") {
        const apiKey = accessToken || process.env.KIRO_API_KEY;
        if (isKiroDeviceAuthKey(apiKey)) {
            return new KiroRestTransport(fetchTransportOptions(options), {
                credentialProvider: async () => (await credentialFromKiroDeviceAuthKey(apiKey).catch(() => undefined)) ?? readKiroCliSessionCredential(),
                login,
            });
        }
        return new KiroRestTransport(fetchTransportOptions(options, apiKey === KIRO_LOCAL_TRANSPORT_KEY ? undefined : apiKey), {
            login,
        });
    }
    return undefined;
}
export function acpTransportOptions(options) {
    return {
        trustAllTools: options.trustAllTools,
        ...(options.requestTimeoutMs ? { promptTimeoutMs: options.requestTimeoutMs } : {}),
    };
}
export function fetchTransportOptions(options, accessToken) {
    return {
        region: options.region,
        ...(accessToken ? { accessToken } : {}),
        maxAttempts: options.maxAttempts,
        ...(options.endpoint ? { endpoint: options.endpoint } : {}),
        ...(options.profileArn ? { profileArn: options.profileArn } : {}),
        ...(options.userAgent ? { userAgent: options.userAgent } : {}),
        ...(options.agentMode ? { agentMode: options.agentMode } : {}),
        ...(options.requestTimeoutMs ? { requestTimeoutMs: options.requestTimeoutMs } : {}),
    };
}
export function createKiroPlugin() {
    return async (_input, rawOptions) => {
        const options = loadOptions(rawOptions);
        const modelCache = new ModelCache(options.modelCacheTtlSeconds);
        let localServer;
        let configuredModels = { ...options.extraModels };
        let userModelOverrides;
        const disabledModels = new Set(options.disabledModels.map(normalizeModelName));
        const stored = await loadStoredModelCache();
        if (stored.models.length > 0) {
            modelCache.update(mergeModelInfos(stored.models, options.extraModels), stored.updatedAt);
        }
        else if (Object.keys(options.extraModels).length > 0) {
            modelCache.update(extraModelInfos(options.extraModels));
        }
        let discovery;
        let lastModelDiscoveryAt = 0;
        let startupDeviceAuthKey = sharedDeviceAuthKey;
        let startupLogin;
        let startupLoginAttempted = false;
        const refreshModels = async (force = false) => {
            const discoveryIsStale = lastModelDiscoveryAt === 0 || Date.now() - lastModelDiscoveryAt > options.modelCacheTtlSeconds * 1000;
            if (options.modelDiscovery === "off" || options.modelDiscoveryCommand.length === 0 || (!force && !discoveryIsStale)) {
                return [];
            }
            if (!discovery) {
                discovery = (async () => {
                    if (isKiroCliModelDiscoveryCommand(options.modelDiscoveryCommand)) {
                        const auth = await detectAuth().catch(() => undefined);
                        if (!auth?.authenticated)
                            return [];
                    }
                    return discoverModelsFromCommand(options.modelDiscoveryCommand[0], options.modelDiscoveryCommand.slice(1));
                })()
                    .then((models) => {
                    if (models.length > 0) {
                        lastModelDiscoveryAt = Date.now();
                        modelCache.update(mergeModelInfos(models, options.extraModels), lastModelDiscoveryAt);
                        void saveStoredModelCache(models, lastModelDiscoveryAt);
                    }
                    return models;
                })
                    .catch(() => [])
                    .finally(() => {
                    discovery = undefined;
                });
            }
            return discovery;
        };
        const ensureStartupAuthenticated = async () => {
            startupDeviceAuthKey ??= sharedDeviceAuthKey;
            if (startupDeviceAuthKey)
                return true;
            const current = await detectAuth().catch(() => undefined);
            if (current?.authenticated)
                return true;
            if (startupLogin)
                return startupLogin;
            if (startupLoginAttempted)
                return false;
            startupLoginAttempted = true;
            startupLogin = (async () => {
                const login = loginOptions(options.login);
                if (isOrganizationLogin(login) && login.identityProvider) {
                    try {
                        const authorization = await authorizeKiroDevice(login);
                        openExternalUrl(kiroDeviceVerificationUrl(login.identityProvider, authorization.userCode));
                        const credential = await pollKiroDeviceToken(authorization, {
                            region: options.region,
                            ...(options.profileArn ? { profileArn: options.profileArn } : {}),
                        });
                        startupDeviceAuthKey = rememberDeviceAuthKey(encodeKiroDeviceAuthKey(credential));
                        return true;
                    }
                    catch {
                        return false;
                    }
                }
                const session = startKiroCliLoginOnce(login);
                const prompted = await session.waitForPrompt(options.requestTimeoutMs);
                if (!prompted)
                    return false;
                return session.waitForAuth();
            })().finally(() => {
                startupLogin = undefined;
            });
            return startupLogin;
        };
        const resolver = new ModelResolver({
            cache: modelCache,
            aliases: options.modelAliases,
            hiddenModels: options.hiddenModels,
            disabledModels: options.disabledModels,
            disablePassThrough: options.disableModelPassThrough,
        });
        const localFetch = async (input, init) => {
            startupDeviceAuthKey ??= sharedDeviceAuthKey;
            const accessToken = localAccessToken(bearerToken(init), startupDeviceAuthKey || sharedDeviceAuthKey);
            const transport = localTransport(options, accessToken, {
                loginOnAuthFailure: shouldLoginOnAuthFailure(init),
            });
            return createKiroFetch({
                resolver,
                models: async () => {
                    await refreshModels(true).catch(() => []);
                    return Object.keys(visibleProviderModels(modelCache, configuredModels, options.hiddenModels, disabledModels));
                },
                ...(transport ? { transport } : {}),
            })(input, init);
        };
        const ensureLocalServer = async () => {
            if (localServer)
                return localServer;
            localServer = await startLocalKiroServer(localFetch);
            return localServer;
        };
        const authorizeCliDeviceLogin = async (inputs) => {
            const login = loginOptions(options.login, inputs);
            if (isOrganizationLogin(login) && login.identityProvider) {
                const authorization = await authorizeKiroDevice(login);
                const url = kiroDeviceVerificationUrl(login.identityProvider, authorization.userCode);
                return {
                    url,
                    instructions: `Open ${url} and confirm code: ${authorization.userCode}`,
                    method: "auto",
                    callback: async () => {
                        try {
                            const credential = await pollKiroDeviceToken(authorization, {
                                region: options.region,
                                ...(options.profileArn ? { profileArn: options.profileArn } : {}),
                            });
                            const key = rememberDeviceAuthKey(encodeKiroDeviceAuthKey(credential));
                            startupDeviceAuthKey = key;
                            await refreshModels(true).catch(() => []);
                            return {
                                type: "success",
                                key,
                                metadata: {
                                    source: "kiro-device-auth",
                                },
                            };
                        }
                        catch {
                            return { type: "failed" };
                        }
                    },
                };
            }
            const session = startKiroCliLoginOnce(login);
            await session.waitForPrompt(options.requestTimeoutMs);
            return {
                url: session.url,
                instructions: session.instructions,
                method: "auto",
                callback: async () => {
                    const authenticated = await session.waitForAuth();
                    if (!authenticated)
                        return { type: "failed" };
                    await refreshModels(true).catch(() => []);
                    return {
                        type: "success",
                        key: KIRO_LOCAL_TRANSPORT_KEY,
                        metadata: {
                            source: "kiro-cli-device-flow",
                        },
                    };
                },
            };
        };
        const authPrompts = loginPrompts(options);
        return {
            dispose: async () => {
                await localServer?.close();
                localServer = undefined;
            },
            config: async (config) => {
                await ensureStartupAuthenticated();
                await refreshModels();
                config.provider ??= {};
                config.provider[options.providerID] ??= {};
                const provider = config.provider[options.providerID];
                const server = await ensureLocalServer();
                userModelOverrides ??= modelRecord(provider.models);
                configuredModels = {
                    ...options.extraModels,
                    ...userModelOverrides,
                };
                provider.name ??= "Kiro";
                provider.npm = "@ai-sdk/openai-compatible";
                provider.api = server.baseURL;
                provider.options ??= {};
                provider.options.baseURL = server.baseURL;
                provider.options.apiKey ??= KIRO_LOCAL_TRANSPORT_KEY;
                provider.models = visibleProviderModels(modelCache, configuredModels, options.hiddenModels, disabledModels);
            },
            auth: {
                provider: options.providerID,
                methods: [
                    {
                        type: "oauth",
                        label: "Kiro device login",
                        ...(authPrompts ? { prompts: authPrompts } : {}),
                        authorize: async (inputs) => authorizeCliDeviceLogin(inputs),
                    },
                    {
                        type: "api",
                        label: "Kiro API key",
                        prompts: [
                            {
                                type: "text",
                                key: "apiKey",
                                message: "Enter KIRO_API_KEY",
                                placeholder: "ksk_...",
                            },
                        ],
                        authorize: async (inputs) => {
                            const key = inputs?.apiKey;
                            if (!key)
                                return { type: "failed" };
                            return { type: "success", key };
                        },
                    },
                ],
                loader: async (auth) => {
                    const apiKey = await resolveApiKey(auth);
                    startupDeviceAuthKey ??= sharedDeviceAuthKey;
                    const server = await ensureLocalServer();
                    return {
                        apiKey: apiKey || startupDeviceAuthKey || sharedDeviceAuthKey || KIRO_LOCAL_TRANSPORT_KEY,
                        baseURL: server.baseURL,
                        fetch: localFetch,
                    };
                },
            },
            tool: {
                kiro_status: tool({
                    description: "Show Kiro plugin backend, auth, region, and discovered model status.",
                    args: {},
                    execute: async () => {
                        const auth = await detectAuth();
                        return {
                            title: "Kiro status",
                            output: [
                                `provider: ${options.providerID}`,
                                `backend: ${options.backend}`,
                                `effective backend: ${effectiveBackend(options)}`,
                                `region: ${auth.region}`,
                                `auth: ${auth.method}`,
                                `authenticated: ${auth.authenticated ? "yes" : "no"}`,
                                `models: ${modelCache.ids().length} discovered/cache entries`,
                                auth.message,
                            ].join("\n"),
                            metadata: {
                                providerID: options.providerID,
                                backend: options.backend,
                                effectiveBackend: effectiveBackend(options),
                                region: auth.region,
                                authMethod: auth.method,
                                authenticated: auth.authenticated,
                            },
                        };
                    },
                }),
                kiro_refresh_models: tool({
                    description: "Refresh the cached Kiro model list on demand.",
                    args: {},
                    execute: async () => {
                        const models = await refreshModels(true);
                        const cached = modelCache.ids();
                        return {
                            title: models.length > 0 ? "Kiro models refreshed" : "Kiro model refresh skipped",
                            output: models.length > 0
                                ? `refreshed: ${models.length}\ncached: ${cached.length}`
                                : `No models were discovered. Keeping cached models: ${cached.length}`,
                            metadata: {
                                refreshed: models.length > 0,
                                discovered: models.length,
                                cached: cached.length,
                            },
                        };
                    },
                }),
            },
            provider: {
                id: options.providerID,
                models: async (provider) => {
                    const existing = modelRecord(provider.models);
                    const visibleModels = visibleProviderModels(modelCache, configuredModels, options.hiddenModels, disabledModels);
                    const server = await ensureLocalServer();
                    return Object.fromEntries(Object.keys(visibleModels)
                        .map((id) => {
                        const model = {
                            ...(visibleModels[id] ?? {}),
                            ...(existing[id] ?? {}),
                        };
                        return [
                            id,
                            {
                                ...model,
                                api: {
                                    ...(model.api ?? {}),
                                    id,
                                    npm: "@ai-sdk/openai-compatible",
                                    url: server.baseURL,
                                },
                            },
                        ];
                    }));
                },
            },
            "chat.headers": async (input, output) => {
                if (input.model.providerID !== options.providerID)
                    return;
                output.headers[OPENCODE_AGENT_HEADER] = input.agent;
            },
        };
    };
}
export const KiroPlugin = createKiroPlugin();
